_Q1 = [("Saan sa Arizona?", "Where in Arizona?"), ("Saan ka ipinanganak?", "Where were you born?"), ("Saan sa Texas?", "Where in Texas?"), ("Saan ka nakatira ngayon?", "Where do you live now?"), ("Saan ka lumaki?", "Where were you raised?"), ("Nasaan na sila ngayon?", "Where are they now?"), ("Ilang taong gulang ka na?", "How old are you now?"), ("Ilan ang kapatid mo?", "How many siblings do you have?"), ("Pang-ilan ka?", "Which order are you?"), ("Kailan ka ipinanganak?", "When were you born?"), ("Ano ang pangalan mo?", "What is your name?"), ("Ano ang ranggo mo?", "What is your rank?"), ("Ano ang apelyido mo?", "What is your last name?"), ("Ano ang palayaw mo?", "What is your nickname?"), ("Ano ang trabaho ng mga magulang mo?", "What is your parents’ occupation?"), ("Ano ang unang pangalan mo?", "What is your first name?")]
