        + [M("Which question word asks about a fixed location or goes with a verb?", "saan", ["nasaan", "ilan", "kailan"], "Saan."), M("Which question word asks where a person or object is, or for places on a map?", "nasaan", ["saan", "ilan", "ano"], "Nasaan."), M("How does the answer to a saan question usually start?", "sa", ["nasa", "ang", "si"], "Sa Phoenix."), M("How does the answer to a nasaan question usually start?", "nasa", ["sa", "ang", "ay"], "Nasa Arizona."), M("What does ilan mean?", "how many", ["when", "where", "which order"], "Ilan."), M("What does pang-ilan mean?", "which order", ["how many", "when", "where"], "Pang-ilan."), M("What kind of numbers answer ilan?", "cardinal numbers", ["ordinal numbers", "Roman numerals", "Spanish words only"], "Cardinal."), M("What kind of numbers answer pang-ilan?", "ordinal numbers", ["cardinal numbers", "dates", "ages"], "Ordinal."), M("What is the g in Ilang taong gulang?", "A linker", ["A plural", "A verb", "A marker"], "Linker."), M("What does kailan mean?", "when", ["where", "who", "how many"], "Kailan."), M("How do native speakers pronounce kailan?", "kelan", ["kalan", "kailin", "kalian"], "Kelan."), M("What is the plural of sino?", "sinu-sino", ["sino-sino", "mga sino", "sinosino"], "Sinu-sino."), M("What is the plural of ano?", "anu-ano", ["ano-ano", "mga ano", "anoano"], "Anu-ano."), M("What is the plural of ilan?", "ilan-ilan", ["ilanilan", "mga ilan", "ilang-ilan"], "Ilan-ilan."), M("Which question words have no plural form?", "nasaan and pang-ilan", ["saan and kailan", "ano and sino", "ilan and kailan"], "No plural form."), M("How is saan often said?", "san", ["sa", "naan", "sain"], "San.")]
